// web/src/AdminLogin.jsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminLogin.css";

export default function AdminLogin({ onBack, onLogin, navigate: navProp }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const navigate = navProp || useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    // valida formato antes de enviar…
    if (onLogin) onLogin({ username, password }, navigate);
    else navigate("/dashboard");
  };

  const handleBack = () => {
    if (onBack) onBack(navigate);
    else navigate("/login");
  };

  return (
    <div className="admin-container">
      <div className="admin-box">
        <h2>Panel de Administrador</h2>
        <form className="admin-form" onSubmit={handleSubmit}>
          <label>Usuario</label>
          <input
            type="text"
            placeholder="Ingresa tu usuario"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
          <label>Contraseña</label>
          <input
            type="password"
            placeholder="••••••••"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button type="submit">Iniciar Sesión</button>
        </form>
        <button className="back-btn" onClick={handleBack}>
          ← Volver
        </button>
      </div>
    </div>
  );
}
